  // [change set] The publish button's hover line. One key per term, joined at
  // runtime, rather than one template with four slots — a term is omitted
  // whenever its count is zero, and each locale needs its own word order and
  // measure word ("3 added" vs "新增 3 项"), which a shared template cannot
  // express. The English terms are bare past participles with no noun, so they
  // are count-invariant and need no plural engine; the two file-count strings
  // do vary, so they carry an explicit _one / _many pair.
  'changeset.added': '{count} added',        // {count} placeholder
  'changeset.edited': '{count} edited',       // {count} placeholder
  'changeset.deleted': '{count} deleted',      // {count} placeholder
  'changeset.restyled': '{count} restyled',     // {count} placeholder
  'changeset.nothing': 'Nothing to publish',
  // Composition-ring caption's accessible name — the on-screen text is just
  // the number (progress rule 5: the number is visible, aria names it).
  'changeset.pending_one': '1 pending change',
  'changeset.pending_many': '{count} pending changes', // {count} placeholder
  'changeset.upload_one': '1 file to upload',
  'changeset.upload_many': '{count} files to upload',  // {count} placeholder
  'changeset.first_one': 'First publish · 1 file',
  'changeset.first_many': 'First publish · {count} files',   // {count} placeholder
  'changeset.remove_suffix': '{count} to remove', // {count} placeholder
  // Unclassified AND no count. Two shapes, because "no local record"
  // has two causes and only one of them is a new site. {target} placeholder.
  'changeset.no_machine_record': 'Publish new site to {target}',
  'changeset.no_machine_record_published': 'Publish to {target}',
  // Same two shapes with the host's name not yet known (it arrives from an
  // async command). Naming the wrong host is worse than naming none.
  'changeset.no_machine_record_bare': 'Publish new site',
  'changeset.no_machine_record_published_bare': 'Publish site',
  // In-flight forms — the tooltip during a publish, where the counts describe
  // work HAPPENING rather than work pending.
  'changeset.uploading_one': '1 file uploading',
  'changeset.uploading_many': '{count} files uploading',  // {count} placeholder
  'changeset.removing_suffix': '{count} removing', // {count} placeholder
  'changeset.publishing': 'Publishing…',
