  'onionpress.deploy_failed': "Publish failed",
  // The success screen answers ONE question: is the site live? The title
  // states the verdict and the subline says what moss is doing about it —
  // neither predicts when, because the string that did ("should resolve
  // within a minute") was shown to a user during an outage where nothing
  // resolved at all. `title` is the confirmed-live wording; the other two
  // cover not-live and not-yet-known.
  'onionpress.success.title': "Your site is live.",
  'onionpress.success.title_not_live': "Your onion site isn't live yet",
  'onionpress.success.title_checking': "Checking whether your onion site is live",
  // Matches the OnionPress plugin's own hardcoded "View site" action label
  // verbatim — this key exists so the frontend's
  // verdict-driven surfaces, which can coalesce onto the SAME toast the
  // plugin raised, read as one consistent confirmation regardless of which
  // side ends up delivering it.
  'onionpress.success.action_view': "View site",
  'onionpress.success.subline_checking': "Published. This usually settles on its own",
  // Shown instead of the generic checking/not-live subline when the receiver
  // reports Tor still mid-bootstrap: names the actual wait, with its live
  // percentage. Informational — publishing over loopback already worked.
  'onionpress.success.subline_tor_connecting': "Published. Tor is still connecting ({pct}%) — the address works once it finishes",  // {pct}
  'onionpress.success.name_caption': "Resolves to your onion address",
  'onionpress.success.name_copy': "Copy link",
  'onionpress.success.address_caption': "Your onion address — needs Tor Browser",
  // ── Publish-verification narrative ──
  // Read ONLY through the host's one publish-verification strings module,
  // which keeps the advisory, receipt, toasts, first-publish modal and the
  // email composer's Send gate from drifting apart. Live: 'onionpress.success.title'.
  // Receipt / rung 1: what the publish row says at commit, before the verdict.
  'publish_verify.uploaded_checking': "Uploaded — checking your site is live…",
  // Rung 2 head (10s–90s); the frontend ticker appends " · m:ss".
  'publish_verify.checking': "Checking your site is live…",
  // Rung 3 head (90s–terminal). Uses an EN dash (–), not the em dash the
  // notice splitter keys on (' — ') — the whole sentence must stay visible at
  // rest rather than folding into the collapsible detail.
  'publish_verify.still_checking': "Still checking – a new Tor address can take a couple of minutes to come online.",
  // Rung 3 alternative head when the receiver reports Tor mid-bootstrap.
  'publish_verify.tor_connecting': "Tor is still connecting ({pct}%).",  // {pct}
  // Terminal diagnosis: title is the advisory head AND the brief NeedsAction
  // toast; body + one diagnosis line form the collapsible detail.
  'publish_verify.terminal_title': "Your post is published, but your site can't be reached over Tor right now.",
  'publish_verify.terminal_body': "This is a connection problem, not a problem with your writing. moss keeps watching and will tell you the moment your site is back.",
  'publish_verify.diag_transport': "Tor isn't answering for your address — your network may be blocking Tor.",
  'publish_verify.diag_takeover': "Visitors currently see an archived backup copy of your site.",
  'publish_verify.diag_down': "OnionPress isn't running.",
  'publish_verify.diag_no_verdict': "The status check isn't reporting, so moss can't confirm your site is reachable.",
  // First-publish modal, terminal state: the check outlives the window.
  'publish_verify.modal_keep_watching': "You can close this window — moss keeps watching.",
  // Receipt Live-row titles for moss-hosting's 3 verification outcomes
  // (`classify_moss_verification`) — `checking`/`live` reuse
  // `publish_verify.checking`/`onionpress.success.title` instead of a new
  // key. The word "live" appears only in those two reused titles.
  'publish_verify.title_unreachable_here': "Published, but moss can't reach your site yet.",
  'publish_verify.title_offline': "Published; this computer is offline, so moss can't check it.",
  'publish_verify.title_incomplete': "Publish didn't complete.",
  // The Live row's own second line, one per `PublishReceiptLive` value that
  // can render a row (`unverifiable` renders no row at all).
  'publish_verify.detail_checking': "Checking…",
  'publish_verify.detail_live': "Home page served the new version",
  'publish_verify.detail_unreachable_here': "Confirmed on the server · not reachable from this computer",
  'publish_verify.detail_offline': "Can't check — this computer looks offline",
  'publish_verify.detail_incomplete': "The server is still serving the previous version",
  'onionpress.view_on_tor': "View on Tor",
  // Success-step title/subline for 'claim' mode — the site is already live,
  // so "Your onion site is live" (the first-publish copy) would be wrong.
  'onionpress.claim.title': "Name claimed",
  'onionpress.claim.subline': "This name now resolves to your onion address",
  // OnionPress settings rows (deployment tab, when OnionPress is the host).
  // ONE row: the publish outcome (the address). The Status (Start/Stop) and
  // No WordPress (admin link + credentials) rows — OnionPress's own menu bar
  // app owns the lifecycle, the logs, the settings, and signs the user into
  // wp-admin with a one-time token, so moss neither duplicates those controls
  // nor shows a password. No Remove row either — the Plugins catalog's
  // standard Uninstall action covers it.
  'onionpress.settings.address': "Onion address",
