    'fm_hint.author': 'Name, oder eine Liste von Namen für Mitwirkende. Jeder Name bekommt eine eigene Seite mit allen Werken.',
    'fm_hint.author_page': 'Diese Seite IST die Seite der Verfassenden für einen Namen. Auf „Ein“ übernimmt sie den Seitentitel, oder du gibst den Namen ein. Die Seite listet die Werke dieser Person; Erwähnungen unter „Verfasst von“ verlinken hierher.',
    'fm_hint.tag_page': 'Diese Seite IST die Schlagwortseite für ein Schlagwort. Auf „Ein“ wird der Seitentitel übernommen, oder du gibst das Schlagwort ein. Die Seite enthält die Liste und ersetzt die automatisch erzeugte Seite.',
    'fm_hint.editor': 'Name, oder eine Liste von Namen für Mitherausgebende. Speist den Begriffstyp, den .moss/config.toml als „editor“ benennt.',
    'fm_hint.location': 'Ortsname, oder eine Liste von Orten. Speist den Begriffstyp, den .moss/config.toml als „location“ benennt. Jeder Name wird in .moss/places.toml nachgeschlagen.',
    'fm_hint.jury': 'Name eines Jurymitglieds, oder eine Liste von Namen. Speist den Begriffstyp, den .moss/config.toml als „jury“ benennt.',
    'fm_hint.title_block': 'Wo der Titelblock steht: after-picture setzt ihn unter das einleitende Bild der Seite; weglassen, damit er zuerst kommt. Ein Ordner legt das per cascade für seine Seiten fest.',
    'fm_hint.editor_page': 'Diese Seite IST die Redaktionsseite für einen Namen. Auf „Ein“ übernimmt sie den Seitentitel, oder du gibst den Namen ein. Die Seite listet die Werke dieser Person; Erwähnungen als Redaktion verlinken hierher.',
    'fm_hint.jury_page': 'Diese Seite IST die Jury-Seite für einen Namen. Auf „Ein“ übernimmt sie den Seitentitel, oder du gibst den Namen ein. Die Seite listet die Werke dieser Person; Erwähnungen in der Jury verlinken hierher.',
    'fm_hint.place_page': 'Diese Seite IST die Ortsseite für einen Namen. Auf „Ein“ übernimmt sie den Seitentitel, oder du gibst den Namen ein. Die Seite listet die Werke zu diesem Ort; Erwähnungen des Ortes verlinken hierher.',
    'fm_hint.byline': 'Angaben unter dem Seitentitel, eine Zeile pro Eintrag, Markdown im Text erlaubt. Nur Anzeige, unabhängig vom Feld „Verfasst von“.',
    'fm_hint.colophon': 'Angaben am Seitenende: wo der Text zuerst erschien, Kurzbiografien von Mitwirkenden, Produktionsangaben.',
    'fm_hint.color': 'Nur für die Startseite eines Ordners: die Akzentfarbe (#rgb oder #rrggbb) für diese Seite und alle Seiten darunter.',
    'fm_hint.publisher': 'Name des Verlags oder der Publikation.',
    'fm_hint.cover': 'Titelbild oder -video oben auf der Seite.',
    'fm_hint.tags': 'Themen-Schlagwörter. Jedes hier genannte Schlagwort bekommt eine eigene Schlagwortseite; #Hashtags im Text fließen nur in die Metadaten ein.',
    'fm_hint.url': 'Eigener Slug (z. B. links → /links/). Fixiert eine dauerhafte Adresse, die Umbenennungen übersteht.',
    'fm_hint.external_url': 'Interne Links und Karten zeigen hierhin statt auf die lokale Seiten-URL.',
    'fm_hint.origin': 'Die Adresse, von der diese Seite importiert wurde. moss import speichert sie als Herkunftsnachweis; die Seite wird dort nicht veröffentlicht.',
    'fm_hint.lang': 'Sprachcode für diese Seite (z. B. en, zh).',
    'fm_hint.weight': 'Reihenfolge als Zahl: kleinere Werte stehen zuerst.',
    'fm_hint.draft': 'Nicht veröffentlicht. Auf deiner Website ausgeblendet, in der Vorschau sichtbar.',
    'fm_hint.listed': 'Ausgeschaltet: ausgeblendet aus Listen, Feeds und der Sitemap, aber weiterhin indexiert und unter ihrer URL erreichbar.',
    'fm_hint.slot': 'Setzt diese Seite in einen benannten Platz im Layout ein (z. B. footer-left).',
    'fm_hint.comments': 'Kommentare auf dieser Seite ein- oder ausschalten.',
    'fm_hint.map': 'Zeigt die Karte auf einer Ortsseite oder der Startseite eines Ortsordners. Standardmäßig an; ausschalten, um sie zu verbergen.',
    'fm_hint.country_map': 'Zeichnet die Tabelle dieser Seite als Karte und färbt jedes Land nach der in by genannten Spalte; levels listet deren Werte vom niedrigsten an.',
    'fm_hint.breadcrumb': 'Überschreibt die Einstellung für den Navigationspfad der ganzen Website für diese Seite.',
    'fm_hint.typesetting': 'Schreibrichtung: horizontal, oder vertikale Spalten von rechts nach links für CJK-Inhalte.',
    'fm_hint.content_width': 'Breite der Inhaltsspalte: default für Fließtext, wide für Raster und Tabellen, full für Dashboards.',
    'fm_hint.layout': 'Layout überschreiben (page oder article). „article“ auf einer Ordner-Indexseite unterdrückt das automatisch eingefügte Titelbild.',
    'fm_hint.translationKey': 'Schlüssel, der Übersetzungen desselben Inhalts miteinander verbindet.',
    'fm_hint.also_in': 'Diese Seite zusätzlich in den Listen anderer Ordner zeigen.',
    'fm_hint.review_of': 'URL des besprochenen Werks. Schaltet die Rezensionsfunktion ein.',
    'fm_hint.rating': 'Deine Bewertung des besprochenen Werks, von 1 bis 5.',
    'fm_hint.children': 'Untergeordnete Seiten unter dem Inhalt anzeigen: ein, aus, oder ein bestimmter Ordner wie [[News]].',
    'fm_hint.sort': 'Sortierung der Unterseiten dieses Ordners: date, weight, title oder eine feste Liste.',
    'fm_hint.series': 'Macht die Unterseiten zu einer fortlaufenden Reihe mit Links zu Zurück und Weiter.',
    'fm_hint.sidebar': 'Veraltet. Verwende stattdessen Unterseiten und Feed-Platz.',
    'fm_hint.children_style': 'Wie untergeordnete Seiten in der Liste dargestellt werden.',
    'fm_hint.children_group': 'Unterseiten nach Jahr gruppieren oder ohne Gruppierung lassen.',
    'fm_hint.children_depth': 'Nur direkte Unterseiten anzeigen oder alle Nachfahren.',
    'fm_hint.children_in': 'Wo der Unterseiten-Feed erscheint: im Seiteninhalt oder in der Seitenleiste.',
    'fm_hint.children_limit': 'Zeigt höchstens so viele Unterseiten; ist die Liste gekürzt, erscheint ein Link „Mehr“.',
    'fm_hint.children_pictures': 'Zeigt in einer Übersichtsliste bis zu so viele eigene Bilder jeder Seite (2 bis 12) als Streifen statt eines Titelbilds.',
    'fm_hint.children_motion': 'Lässt in einer Übersichtsliste mit Bildern den Streifen jeder Zeile in einer Schleife seitwärts gleiten (marquee). Für Leser, die weniger Bewegung wünschen, bleibt er still.',
    'fm_hint.route': 'Zeichnet die Orte dieser Seite als Route auf ihrer Ortskarte, in der aufgeführten Reihenfolge.',
    'fm_hint.syndicate': 'Die Netzwerke, in denen nach der Veröffentlichung eine Kopie dieser Seite erscheint, nach Kanal-ID. Meist einmal für einen Ordner mit cascade: gesetzt. false veröffentlicht keine Kopie.',
    'fm_hint.children_more': 'Wiki-Link zur Seite, auf die der Link „Mehr“ zeigen soll; funktioniert auch, wenn diese Seite ihren eigenen Ordner auflistet.',
    'fm_hint.children_when': 'Zeigt nur Unterseiten, deren Termin vorbei ist (past) oder noch aussteht (upcoming).',
