    'fm_hint.contents': 'pictures zeigt im Inhaltsverzeichnis neben dem Text auf breiten Bildschirmen ein kleines Bild jedes Abschnitts; weglassen für die einfache Liste.',
    'fm_hint.children_covers': 'Nur Unterseiten mit Titelbild behalten. Auf „only“ setzen. Nützlich für eine Startseite, die die neuesten illustrierten Seiten zeigt.',
